import {options,prepare,bettingCommand} from './engine.mjs';
import {mountBoard} from './board.mjs';
import {summarizeRun,percentile,createRunReport,reportFilename} from './report.mjs';
let lastReport;
const releasePromise=Promise.race([fetch('./release.json',{cache:'no-store'}).then(r=>r.ok?r.json():{}).catch(()=>({})),new Promise(resolve=>setTimeout(()=>resolve({}),3000))]);
const $=id=>document.getElementById(id);let pockets=37,bets=[{type:'red',value:'',amount:10,every:1,start:1}],worker;
const types={red:'Red · 1:1',black:'Black · 1:1',odd:'Odd · 1:1',even:'Even · 1:1',low:'1–18 · 1:1',high:'19–36 · 1:1',dozen:'Dozen · 2:1',column:'Column · 2:1',straight:'Single number · 35:1',split:'Split · 17:1',street:'Street · 11:1',corner:'Corner · 8:1',six:'Six-line · 5:1',basket:'0, 00, 1, 2, 3 · 6:1'};
const help={flat:'Use each rule’s amount whenever it is due. A useful baseline for any experiment.',martingale:'Double after a net loss; reset after a net win. Stakes can grow very quickly.',reverse:'Double after a net win; reset after a loss or the selected win streak.',fibonacci:'After losses: 1, 1, 2, 3, 5… units. After a win, move back two steps.',dalembert:'Add one unit after a net loss; subtract one after a win, never below one.'};
const fmt=n=>new Intl.NumberFormat('en',{maximumFractionDigits:2}).format(n),money=n=>(n<-.005?'−':n>.005?'+':'')+'¤'+fmt(Math.abs(n)),pct=n=>(n*100).toFixed(1)+'%';
function renderBets(){const root=$('bets');root.replaceChildren();bets.forEach((b,i)=>{const row=document.createElement('div');row.className='bet scheduled-bet';const top=document.createElement('div');top.className='rule-top';const title=document.createElement('b');title.textContent='Rule '+(i+1);const rem=document.createElement('button');rem.textContent='Remove';rem.className='text-button';rem.setAttribute('aria-label','Remove rule '+(i+1));rem.disabled=false;rem.onclick=()=>{bets.splice(i,1);renderBets();dirty();};top.append(title,rem);row.append(top);const select=document.createElement('select');select.setAttribute('aria-label','Bet type for rule '+(i+1));for(const[k,v]of Object.entries(types)){if(k==='basket'&&pockets!==38)continue;select.add(new Option(v,k));}select.value=b.type;select.onchange=()=>{b.type=select.value;b.value=options(b.type,pockets)[0]?.value||'';renderBets();dirty();};row.append(select);const opts=options(b.type,pockets);if(opts.length){if(!opts.some(o=>o.value===b.value))b.value=opts[0].value;const detail=document.createElement('select');detail.setAttribute('aria-label','Numbers for rule '+(i+1));for(const o of opts)detail.add(new Option(o.label,o.value));detail.value=b.value;detail.onchange=()=>{b.value=detail.value;dirty();};row.append(detail);}const grid=document.createElement('div');grid.className='rule-fields';for(const[key,label,max]of [['amount','Amount',1000000],['every','Every N',100000],['start','Start spin',100000]]){const wrap=document.createElement('div'),l=document.createElement('label'),input=document.createElement('input');input.id='rule'+i+key;l.htmlFor=input.id;l.textContent=label;input.type='number';input.min=1;input.max=max;input.step=1;input.value=b[key];input.oninput=()=>{b[key]=Number(input.value);dirty();};wrap.append(l,input);grid.append(wrap);}row.append(grid);root.append(row);});$('addBet').disabled=bets.length>=20;if(!bets.length){const note=document.createElement('p');note.className='hint';note.textContent='No rules yet. Choose a placement on the table above.';root.append(note);}}
let target;
function sentence(){$('commandSentence').textContent=bettingCommand(target,{amount:+$('commandAmount').value,every:+$('commandEvery').value,start:+$('commandStart').value});}
function board(){mountBoard(pockets,b=>{target=b;$('selectedTarget').textContent=b.label;$('commandTarget').value=b.label;$('selectedPayout').textContent=`${b.nums.length} covered pocket${b.nums.length===1?'':'s'} · pays ${b.payout}:1 profit`;$('commandError').textContent='';sentence();});}
for(const id of ['commandAmount','commandEvery','commandStart'])$(id).oninput=sentence;
$('addCommand').onclick=()=>{for(const id of ['commandAmount','commandEvery','commandStart'])if(!$(id).checkValidity()||!$(id).value){$('commandError').textContent='Enter positive whole-number amounts and spin numbers.';return;}if(bets.length>=20){$('commandError').textContent='Up to 20 rules per experiment.';return;}bets.push({type:target.type,value:target.value,amount:+$('commandAmount').value,every:+$('commandEvery').value,start:+$('commandStart').value});renderBets();dirty();$('commandError').textContent='Rule added. Edit or remove it below.';};
board();sentence();
function dirty(){if(!$('output').hidden)$('status').textContent='Settings changed · run again';}
$('addBet').onclick=()=>{if(bets.length<20){bets.push({type:'straight',value:'17',amount:+$('base').value||10,every:3,start:3});renderBets();dirty();}};
document.querySelectorAll('[data-wheel]').forEach(b=>b.onclick=()=>{pockets=+b.dataset.wheel;document.querySelectorAll('[data-wheel]').forEach(x=>x.classList.toggle('active',x===b));bets.forEach(x=>{if(x.type==='basket'&&pockets!==38){x.type='red';x.value='';}});$('edge').textContent=`${pockets} pockets · ${((pockets-36)/pockets*100).toFixed(2)}% standard house edge`;$('emptyEdge').textContent=((pockets-36)/pockets*100).toFixed(2)+'%';renderBets();board();dirty();});
$('strategy').onchange=()=>{$('strategyHelp').textContent=help[$('strategy').value]+' Break-even spins leave the progression unchanged.';dirty();};$('strategy').onchange();renderBets();document.querySelectorAll('.controls input,.controls select').forEach(e=>e.addEventListener('input',dirty));
function config(){const c={pockets,strategy:$('strategy').value,limitRule:$('limitRule').value,seed:$('seed').value,bets:structuredClone(bets)};for(const id of ['bankroll','base','spins','sessions','tableMax','takeProfit','stopLoss','resetWins']){const e=$(id);if(!e.checkValidity()||!e.value.trim())throw Error('Check '+e.labels?.[0]?.textContent+'.');c[id]=Number(e.value);}if(c.spins*c.sessions>10000000)throw Error('Choose at most 10 million total spins (spins × sessions).');if(!c.seed.trim())throw Error('Enter a seed so the experiment can be repeated.');if(!c.bets.length)throw Error('Add at least one betting rule on the table.');for(const b of c.bets){for(const key of ['amount','every','start'])if(!Number.isInteger(b[key])||b[key]<1||b[key]>(key==='amount'?1000000:100000))throw Error('Each rule needs valid positive whole-number amounts and spin numbers.');}return c;}
function finishWorker(){worker?.terminate();worker=null;$('run').disabled=false;$('cancel').hidden=true;}
function simulationFailed(){finishWorker();$('status').textContent='Run failed';$('error').textContent='The simulation could not run. Please try again.';}
$('cancel').onclick=()=>{finishWorker();$('status').textContent='Run canceled';};
$('run').onclick=()=>{
  let c;try{c=config();$('error').textContent='';}catch(e){$('error').textContent=e.message;return;}
  $('run').disabled=true;$('cancel').hidden=false;$('status').textContent='Simulating…';
  const startedAt=new Date().toISOString(),startedMs=performance.now();
  try{
    const activeWorker=new Worker('./worker.mjs',{type:'module'});worker=activeWorker;
    activeWorker.onmessage=e=>{
      if(worker!==activeWorker)return;
      if(e.data.progress!==undefined){$('status').textContent=`Simulating · ${Math.round(e.data.progress*100)}%`;return;}
      finishWorker();
      if(e.data.error){$('status').textContent='Run failed';$('error').textContent=e.data.error;return;}
      show(e.data.results,c,{startedAt,completedAt:new Date().toISOString(),durationMs:performance.now()-startedMs,userAgent:navigator.userAgent});
    };
    activeWorker.onerror=()=>{if(worker===activeWorker)simulationFailed();};
    activeWorker.postMessage(c);
  }catch{simulationFailed();}
};
function show(r,c,meta){lastReport={results:r,config:structuredClone(c),meta};void prepareDownload(lastReport);$('empty').hidden=true;$('output').hidden=false;$('status').textContent=`${fmt(r.length)} sessions complete`;$('resultTitle').textContent=`${$('strategy').options[Array.from($('strategy').options).findIndex(x=>x.value===c.strategy)].text} · ${c.pockets} pockets`;
const {count:n,totals,mean,wins,ties,ruins,zero,se,sorted,reasons}=summarizeRun(r),sum=k=>totals[k];$('mean').textContent=money(mean);$('meanNote').textContent=n>1?`Monte Carlo standard error: ¤${fmt(se)}`:'One session cannot estimate sampling error.';$('win').textContent=pct(wins/n);$('winNote').textContent=`${fmt(wins)} ahead · ${fmt(ties)} break-even`;$('ruin').textContent=pct(ruins/n);$('ruinNote').textContent=`${fmt(ruins)} stopped · ${fmt(zero)} finished at zero`;
const q=p=>percentile(sorted,p);$('p10').textContent=money(q(.1));$('median').textContent=money(q(.5));$('p90').textContent=money(q(.9));
const rows=[['Starting bankroll, each session','¤'+fmt(c.bankroll)],['Total amount wagered, all sessions','¤'+fmt(sum('wagered'))],['Total profit / loss, all sessions',money(sum('profit'))],['Average amount wagered','¤'+fmt(sum('wagered')/n)],['Average house-edge cost benchmark',money(sum('benchmark')/n)],['Actual spins played',fmt(sum('spins'))+' / '+fmt(c.spins*c.sessions)],['Average spins per session',fmt(sum('spins')/n)],['Spins with money wagered',fmt(sum('wageringSpins'))],['Spins without any bets',fmt(sum('spins')-sum('wageringSpins'))],['Random seed',c.seed]];const dl=$('audit');dl.replaceChildren();for(const [k,v]of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dd.style.overflowWrap='anywhere';dl.append(dt,dd);}$('benchmarkNote').textContent='The benchmark sums −stake × house edge for every wager. With adaptive stakes it is a cost benchmark, not a prediction conditional on this run’s turnover. Across many experiments, mean profit and mean benchmark converge in expectation. Sampling error is the standard deviation of session profits divided by √sessions; rare losses may still be undersampled.';$('reasons').replaceChildren();for(const [k,v]of Object.entries(reasons)){const div=document.createElement('div');div.className='reason';const b=document.createElement('b');b.textContent=pct(v/n);div.append(b,document.createTextNode(k));$('reasons').append(div);}$('limitNote').textContent=`${fmt(r.filter(x=>x.limitHits).length)} sessions hit a table limit. Policy: ${c.limitRule==='stop'?'end the session':c.limitRule==='reset'?'reset the progression to its base':'cap all stakes proportionally and continue the progression'}. Every repeated session starts fresh. Results shown use the settings at the time of the run.`;drawPaths(r.slice(0,12),c);drawHistogram(sorted);if(innerWidth<741)document.querySelector('.results').scrollIntoView({behavior:'smooth',block:'start'});}
const NS='http://www.w3.org/2000/svg';function svgEl(root,tag,attrs,text){const el=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;root.append(el);return el;}
const short=n=>Math.abs(n)>=1000000?(n/1000000).toFixed(1)+'m':Math.abs(n)>=10000?(n/1000).toFixed(0)+'k':fmt(n);
function drawPaths(r,c){const root=$('paths');root.replaceChildren();const all=r.flatMap(x=>x.path.map(p=>p.y));let lo=Math.min(0,...all),hi=Math.max(0,...all);if(lo===hi){lo=-1;hi=1;}const pad=(hi-lo)*.08;lo-=pad;hi+=pad;const x=s=>64+s/c.spins*670,y=v=>225-(v-lo)/(hi-lo)*210;for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;svgEl(root,'line',{x1:64,x2:734,y1:y(v),y2:y(v),stroke:'#e9ede5'});svgEl(root,'text',{x:54,y:y(v)+3,'text-anchor':'end'},short(v));}svgEl(root,'line',{x1:64,x2:734,y1:y(0),y2:y(0),stroke:'#8d9b86','stroke-dasharray':'4 5'});r.forEach((s,i)=>svgEl(root,'polyline',{points:s.path.map(p=>x(p.x)+','+y(p.y)).join(' '),fill:'none',stroke:['#49775e','#ba7656','#92a879','#92a5a0','#c5a260','#385a48'][i%6],'stroke-width':i===0?2:1.2,opacity:i===0?1:.65}));for(const t of [0,.25,.5,.75,1])svgEl(root,'text',{x:x(c.spins*t),y:247,'text-anchor':'middle'},short(c.spins*t));svgEl(root,'text',{x:400,y:268,'text-anchor':'middle'},'Spins played');}
function drawHistogram(sorted){const root=$('hist');root.replaceChildren();let lo=sorted[0],hi=sorted.at(-1);if(lo===hi){lo-=1;hi+=1;}const count=24,bins=Array(count).fill(0),width=(hi-lo)/count;for(const v of sorted)bins[Math.min(count-1,Math.floor((v-lo)/width))]++;const max=Math.max(...bins),x=i=>64+i/count*670;for(let i=0;i<=3;i++){const n=max*i/3,y=165-n/max*145;svgEl(root,'line',{x1:64,x2:734,y1:y,y2:y,stroke:'#edf0e9'});svgEl(root,'text',{x:54,y:y+3,'text-anchor':'end'},fmt(Math.round(n)));}bins.forEach((n,i)=>{const rect=svgEl(root,'rect',{x:x(i)+1,y:165-n/max*145,width:670/count-2,height:n/max*145,rx:2,fill:lo+(i+.5)*width<0?'#c17e61':'#6a9271'});svgEl(rect,'title',{},`${money(lo+i*width)} to ${money(lo+(i+1)*width)}: ${n} sessions`);});for(const t of [0,.25,.5,.75,1])svgEl(root,'text',{x:64+t*670,y:185,'text-anchor':'middle'},short(lo+t*(hi-lo)));svgEl(root,'text',{x:400,y:207,'text-anchor':'middle'},'Final session profit · bar height = session count');}

async function prepareDownload(completedRun){
  const release=await releasePromise;
  if(completedRun!==lastReport)return;
  const meta={...completedRun.meta,...release};
  const text=createRunReport(completedRun.results,completedRun.config,meta);
  const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));
  const link=$('downloadReport'),previous=link.getAttribute('href');
  link.href=url;link.download=reportFilename(meta.completedAt);
  if(previous?.startsWith('blob:'))setTimeout(()=>URL.revokeObjectURL(previous),60000);
  $('reportActions').hidden=false;
}
